import org.apache.commons.cli2.Option;
import org.apache.commons.cli2.commandline.WriteableCommandLineImpl;
import org.apache.commons.cli2.option.DefaultOption;
import org.junit.Before;
import org.junit.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.*;

public class WriteableCommandLineImplGetValuesTest {

    private WriteableCommandLineImpl commandLine;
    private Option mockOption;
    private Option anotherMockOption;

    @Before
    public void setUp() {
        mockOption = new DefaultOption("test", "test", 0, 1, true, null, null, null, null, 't');
        anotherMockOption = new DefaultOption("another", "another", 0, 1, true, null, null, null, null, 'a');
        commandLine = new WriteableCommandLineImpl(mockOption, new ArrayList());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testGetValues_NullOption() {
        commandLine.getValues(null, Collections.emptyList());
    }

    @Test
    public void testGetValues_ExplicitlySetValues() {
        commandLine.addValue(mockOption, "value1");
        commandLine.addValue(mockOption, "value2");

        List<String> result = commandLine.getValues(mockOption, Arrays.asList("fallback1"));
        assertEquals(2, result.size());
        assertTrue(result.contains("value1"));
        assertTrue(result.contains("value2"));
        assertNotSame(result, commandLine.values.get(mockOption)); // Ensure new mutable list
        result.add("newValue"); // Test mutability
        assertEquals(3, result.size());
    }

    @Test
    public void testGetValues_NoExplicitValues_WithFallback() {
        List<String> fallback = Arrays.asList("fallback1", "fallback2");
        List<String> result = commandLine.getValues(mockOption, fallback);
        assertEquals(2, result.size());
        assertTrue(result.contains("fallback1"));
        assertTrue(result.contains("fallback2"));
        assertNotSame(result, fallback); // Ensure new mutable list
        result.add("newValue"); // Test mutability
        assertEquals(3, result.size());
    }

    @Test
    public void testGetValues_NoExplicitValues_NullFallback() {
        List<String> internalDefaults = Arrays.asList("internal1", "internal2");
        commandLine.setDefaultValues(mockOption, internalDefaults);

        List<String> result = commandLine.getValues(mockOption, null);
        assertEquals(2, result.size());
        assertTrue(result.contains("internal1"));
        assertTrue(result.contains("internal2"));
        assertNotSame(result, internalDefaults); // Ensure new mutable list
        result.add("newValue"); // Test mutability
        assertEquals(3, result.size());
    }

    @Test
    public void testGetValues_NoExplicitValues_EmptyFallback() {
        List<String> internalDefaults = Arrays.asList("internal1", "internal2");
        commandLine.setDefaultValues(mockOption, internalDefaults);

        List<String> result = commandLine.getValues(mockOption, Collections.emptyList());
        assertEquals(2, result.size());
        assertTrue(result.contains("internal1"));
        assertTrue(result.contains("internal2"));
        assertNotSame(result, internalDefaults); // Ensure new mutable list
        result.add("newValue"); // Test mutability
        assertEquals(3, result.size());
    }

    @Test
    public void testGetValues_NoExplicitValues_NoFallback_WithInternalDefaults() {
        List<String> internalDefaults = Arrays.asList("internal1", "internal2");
        commandLine.setDefaultValues(mockOption, internalDefaults);

        List<String> result = commandLine.getValues(mockOption, null);
        assertEquals(2, result.size());
        assertTrue(result.contains("internal1"));
        assertTrue(result.contains("internal2"));
        assertNotSame(result, internalDefaults); // Ensure new mutable list
        result.add("newValue"); // Test mutability
        assertEquals(3, result.size());
    }

    @Test
    public void testGetValues_NoValuesFound_ReturnsEmptyList() {
        List<String> result = commandLine.getValues(mockOption, null);
        assertTrue(result.isEmpty());
        // Ensure it's an immutable empty list
        try {
            result.add("shouldFail");
            fail("Should have thrown UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            // Expected
        }
    }

    @Test
    public void testGetValues_NoValuesFound_EmptyFallback_NoInternalDefaults() {
        List<String> result = commandLine.getValues(mockOption, Collections.emptyList());
        assertTrue(result.isEmpty());
        // Ensure it's an immutable empty list
        try {
            result.add("shouldFail");
            fail("Should have thrown UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            // Expected
        }
    }

    @Test
    public void testGetValues_NoValuesFound_NullFallback_NoInternalDefaults() {
        List<String> result = commandLine.getValues(mockOption, null);
        assertTrue(result.isEmpty());
        // Ensure it's an immutable empty list
        try {
            result.add("shouldFail");
            fail("Should have thrown UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            // Expected
        }
    }

    @Test
    public void testGetValues_ExplicitValuesOverrideFallbackAndInternal() {
        commandLine.addValue(mockOption, "explicit1");
        commandLine.setDefaultValues(mockOption, Arrays.asList("internal1"));

        List<String> result = commandLine.getValues(mockOption, Arrays.asList("fallback1"));
        assertEquals(1, result.size());
        assertEquals("explicit1", result.get(0));
    }

    @Test
    public void testGetValues_FallbackOverridesInternalIfNoExplicit() {
        commandLine.setDefaultValues(mockOption, Arrays.asList("internal1"));

        List<String> result = commandLine.getValues(mockOption, Arrays.asList("fallback1"));
        assertEquals(1, result.size());
        assertEquals("fallback1", result.get(0));
    }

    @Test
    public void testGetValues_InternalDefaultsUsedWhenNoExplicitOrFallback() {
        commandLine.setDefaultValues(mockOption, Arrays.asList("internal1", "internal2"));

        List<String> result = commandLine.getValues(mockOption, null);
        assertEquals(2, result.size());
        assertTrue(result.contains("internal1"));
        assertTrue(result.contains("internal2"));
    }

    @Test
    public void testGetValues_DifferentOptionHasNoValues() {
        commandLine.addValue(mockOption, "value1");
        List<String> result = commandLine.getValues(anotherMockOption, null);
        assertTrue(result.isEmpty());
    }

    @Test
    public void testGetValues_DifferentOptionHasInternalDefaults() {
        commandLine.setDefaultValues(anotherMockOption, Arrays.asList("anotherInternal"));
        List<String> result = commandLine.getValues(anotherMockOption, null);
        assertEquals(1, result.size());
        assertEquals("anotherInternal", result.get(0));
    }

    @Test
    public void testGetValues_ReturnedListIsMutable() {
        commandLine.addValue(mockOption, "initial");
        List<String> result = commandLine.getValues(mockOption, null);
        assertFalse(result.isEmpty());
        result.add("added");
        assertEquals(2, result.size());
        assertTrue(result.contains("added"));
    }

    @Test
    public void testGetValues_ReturnedListDoesNotAffectInternalState() {
        commandLine.addValue(mockOption, "initial");
        List<String> result = commandLine.getValues(mockOption, null);
        result.add("added");

        // Get values again, should not see "added"
        List<String> secondResult = commandLine.getValues(mockOption, null);
        assertEquals(1, secondResult.size());
        assertEquals("initial", secondResult.get(0));
    }

    @Test
    public void testGetValues_InternalDefaultValuesAreNotModifiedByCaller() {
        List<String> internalDefaults = new ArrayList<>(Arrays.asList("internal1"));
        commandLine.setDefaultValues(mockOption, internalDefaults);

        List<String> result = commandLine.getValues(mockOption, null);
        result.add("addedToResult");

        // Check if the original internalDefaults list was modified
        assertEquals(1, internalDefaults.size());
        assertEquals("internal1", internalDefaults.get(0));
    }

    @Test
    public void testGetValues_FallbackDefaultValuesAreNotModifiedByCaller() {
        List<String> fallback = new ArrayList<>(Arrays.asList("fallback1"));
        List<String> result = commandLine.getValues(mockOption, fallback);
        result.add("addedToResult");

        // Check if the original fallback list was modified
        assertEquals(1, fallback.size());
        assertEquals("fallback1", fallback.get(0));
    }
}
