import org.apache.commons.codec.binary.StringUtils;
import org.junit.Test;
import static org.junit.Assert.*;

import java.nio.charset.StandardCharsets;

public class StringUtilsNewStringIso8859_1Test {

    @Test
    public void testNewStringIso8859_1_NullInput() {
        assertNull(StringUtils.newStringIso8859_1(null));
    }

    @Test
    public void testNewStringIso8859_1_EmptyByteArray() {
        byte[] bytes = {};
        assertEquals("", StringUtils.newStringIso8859_1(bytes));
    }

    @Test
    public void testNewStringIso8859_1_BasicAscii() {
        byte[] bytes = "Hello".getBytes(StandardCharsets.ISO_8859_1);
        assertEquals("Hello", StringUtils.newStringIso8859_1(bytes));
    }

    @Test
    public void testNewStringIso8859_1_WithSpecialCharacters() {
        // ISO-8859-1 includes characters like é, à, ç, ü
        String original = "Crème brûlée à la française";
        byte[] bytes = original.getBytes(StandardCharsets.ISO_8859_1);
        assertEquals(original, StringUtils.newStringIso8859_1(bytes));
    }

    @Test
    public void testNewStringIso8859_1_AllPossibleBytes() {
        byte[] bytes = new byte[256];
        for (int i = 0; i < 256; i++) {
            bytes[i] = (byte) i;
        }
        // Construct the expected string by manually converting each byte to its ISO-8859-1 char
        StringBuilder expected = new StringBuilder();
        for (int i = 0; i < 256; i++) {
            expected.append((char) (i & 0xFF)); // Ensure it's treated as unsigned byte for char conversion
        }
        assertEquals(expected.toString(), StringUtils.newStringIso8859_1(bytes));
    }

    @Test
    public void testNewStringIso8859_1_LongString() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 1000; i++) {
            sb.append("test" + i + " ");
        }
        String longString = sb.toString();
        byte[] bytes = longString.getBytes(StandardCharsets.ISO_8859_1);
        assertEquals(longString, StringUtils.newStringIso8859_1(bytes));
    }

    @Test
    public void testNewStringIso8859_1_BytesWithZeroValue() {
        byte[] bytes = {72, 101, 108, 108, 111, 0, 87, 111, 114, 108, 100}; // "Hello\0World"
        assertEquals("Hello\0World", StringUtils.newStringIso8859_1(bytes));
    }

    @Test
    public void testNewStringIso8859_1_BytesRepresentingHighAscii() {
        // Example: £ (pound sign) is byte 0xA3 in ISO-8859-1
        byte[] bytes = {(byte) 0xA3, 49, 48, 48}; // £100
        assertEquals("£100", StringUtils.newStringIso8859_1(bytes));
    }
}
