        int bytesRead = b64is.read(buffer, 0, 2); // "lo"
        assertEquals(2, bytesRead);
        assertEquals("lo", new String(buffer, 0, bytesRead, StandardCharsets.US_ASCII));

        assertEquals(-1, b64is.read()); // End of stream
        b64is.close();
    }
