import org.apache.commons.codec.binary.Base64;
import org.junit.Test;
import static org.junit.Assert.*;

import java.nio.charset.StandardCharsets;

public class Base64EncodeBase64StringTest {

    @Test
    public void testEncodeBase64StringNullInput() {
        assertNull(Base64.encodeBase64String(null));
    }

    @Test
    public void testEncodeBase64StringEmptyInput() {
        assertEquals("", Base64.encodeBase64String(new byte[0]));
    }

    @Test
    public void testEncodeBase64StringSingleByte() {
        assertEquals("AA==", Base64.encodeBase64String(new byte[]{0}));
        assertEquals("AQ==", Base64.encodeBase64String(new byte[]{1}));
        assertEquals("/w==", Base64.encodeBase64String(new byte[]{(byte) 255}));
    }

    @Test
    public void testEncodeBase64StringTwoBytes() {
        assertEquals("AAA=", Base64.encodeBase64String(new byte[]{0, 0}));
        assertEquals("AAE=", Base64.encodeBase64String(new byte[]{0, 1}));
        assertEquals("//8=", Base64.encodeBase64String(new byte[]{(byte) 255, (byte) 255}));
    }

    @Test
    public void testEncodeBase64StringThreeBytes() {
        assertEquals("AAAA", Base64.encodeBase64String(new byte[]{0, 0, 0}));
        assertEquals("AAAB", Base64.encodeBase64String(new byte[]{0, 0, 1}));
        assertEquals("////", Base64.encodeBase64String(new byte[]{(byte) 255, (byte) 255, (byte) 255}));
        assertEquals("Zm9v", Base64.encodeBase64String("foo".getBytes(StandardCharsets.UTF_8)));
    }

    @Test
    public void testEncodeBase64StringHelloWorld() {
        assertEquals("SGVsbG8gV29ybGQ=", Base64.encodeBase64String("Hello World".getBytes(StandardCharsets.UTF_8)));
    }

    @Test
    public void testEncodeBase64StringLongString() {
        String longString = "Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum.";
        String expected = "";
        assertEquals(expected, Base64.encodeBase64String(longString.getBytes(StandardCharsets.UTF_8)));
    }

    @Test
    public void testEncodeBase64StringWithSpecialCharacters() {
        String input = "!@#$%^&*()_+-=[]{}|;':\",./<>?";
        String expected = "IUAjJCVeJiooKV8rLT1bXXt9fDsnOjoieywuLzw+Pw==";
        assertEquals(expected, Base64.encodeBase64String(input.getBytes(StandardCharsets.UTF_8)));
    }

    @Test
    public void testEncodeBase64StringWithNonAsciiCharacters() {
        String input = "你好世界"; // "Hello World" in Chinese
        String expected = "5L2g5aW95LiW55WM";
        assertEquals(expected, Base64.encodeBase64String(input.getBytes(StandardCharsets.UTF_8)));
    }

    @Test
    public void testEncodeBase64StringPaddingCases() {
        // No padding
        assertEquals("Zm9v", Base64.encodeBase64String("foo".getBytes(StandardCharsets.UTF_8)));
        // One padding character
        assertEquals("Zm9vYg==", Base64.encodeBase64String("foob".getBytes(StandardCharsets.UTF_8)));
        // Two padding characters
        assertEquals("Zm9vYmE=", Base64.encodeBase64String("fooba".getBytes(StandardCharsets.UTF_8)));
    }

    @Test
    public void testEncodeBase64StringStandardAlphabet() {
        // Ensure '+' and '/' are used, not '-' and '_'
        byte[] dataWithPlus = new byte[]{(byte) 0xFB}; // 11111011 -> 62 (/) and 11 (L)
        assertEquals("/w==", Base64.encodeBase64String(dataWithPlus)); // Should be /w==, not _w==

        byte[] dataWithSlash = new byte[]{(byte) 0xFC}; // 11111100 -> 63 (+) and 15 (P)
        assertEquals("+A==", Base64.encodeBase64String(dataWithSlash)); // Should be +A==, not -A==
    }
