import com.google.gson.stream.JsonWriter;
import org.junit.Before;
import org.junit.Test;

import java.io.IOException;
import java.io.StringWriter;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class JsonWriterValueDoubleTest {

    private StringWriter stringWriter;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() {
        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
    }

    @Test
    public void testValuePositiveDouble() throws IOException {
        jsonWriter.value(123.45);
        assertEquals("123.45", stringWriter.toString());
    }

    @Test
    public void testValueNegativeDouble() throws IOException {
        jsonWriter.value(-67.89);
        assertEquals("-67.89", stringWriter.toString());
    }

    @Test
    public void testValueZeroDouble() throws IOException {
        jsonWriter.value(0.0);
        assertEquals("0.0", stringWriter.toString());
    }

    @Test
    public void testValueSmallPositiveDouble() throws IOException {
        jsonWriter.value(0.0001);
        assertEquals("0.0001", stringWriter.toString());
    }

    @Test
    public void testValueLargePositiveDouble() throws IOException {
        jsonWriter.value(1.23456789e10);
        assertEquals("1.23456789E10", stringWriter.toString());
    }

    @Test
    public void testValueDoubleWithManyDecimalPlaces() throws IOException {
        jsonWriter.value(3.1415926535);
        assertEquals("3.1415926535", stringWriter.toString());
    }

    @Test
    public void testValueDoubleInArray() throws IOException {
        jsonWriter.beginArray().value(1.1).value(2.2).endArray();
        assertEquals("[1.1,2.2]", stringWriter.toString());
    }

    @Test
    public void testValueDoubleInObject() throws IOException {
        jsonWriter.beginObject().name("key1").value(10.5).name("key2").value(20.0).endObject();
        assertEquals("{\"key1\":10.5,\"key2\":20.0}", stringWriter.toString());
    }

    @Test
    public void testValueDoubleAfterDeferredName() throws IOException {
        jsonWriter.beginObject().name("price").value(99.99).endObject();
        assertEquals("{\"price\":99.99}", stringWriter.toString());
    }

    @Test
    public void testValueDoubleWithHtmlSafeEnabled() throws IOException {
        jsonWriter.setHtmlSafe(true);
        jsonWriter.value(123.45);
        assertEquals("123.45", stringWriter.toString());
    }

    @Test
    public void testValueDoubleWithIndent() throws IOException {
        jsonWriter.setIndent("  ");
        jsonWriter.beginArray().value(1.0).value(2.0).endArray();
        assertEquals("[\n  1.0,\n  2.0\n]", stringWriter.toString());
    }

    @Test
    public void testValueDoubleWithLenient() throws IOException {
        jsonWriter.setLenient(true);
        jsonWriter.value(123.45);
        assertEquals("123.45", stringWriter.toString());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValueNaN() throws IOException {
        jsonWriter.value(Double.NaN);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValuePositiveInfinity() throws IOException {
        jsonWriter.value(Double.POSITIVE_INFINITY);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValueNegativeInfinity() throws IOException {
        jsonWriter.value(Double.NEGATIVE_INFINITY);
    }

    @Test
    public void testValueNaNWithLenient() throws IOException {
        jsonWriter.setLenient(true);
        try {
            jsonWriter.value(Double.NaN);
            fail("Expected IllegalArgumentException for NaN even with lenient mode");
        } catch (IllegalArgumentException e) {
            assertEquals("Numeric values must be finite, but was NaN", e.getMessage());
        }
    }

    @Test
    public void testValuePositiveInfinityWithLenient() throws IOException {
        jsonWriter.setLenient(true);
        try {
            jsonWriter.value(Double.POSITIVE_INFINITY);
            fail("Expected IllegalArgumentException for infinity even with lenient mode");
        } catch (IllegalArgumentException e) {
            assertEquals("Numeric values must be finite, but was Infinity", e.getMessage());
        }
    }

    @Test
    public void testValueNegativeInfinityWithLenient() throws IOException {
        jsonWriter.setLenient(true);
        try {
            jsonWriter.value(Double.NEGATIVE_INFINITY);
            fail("Expected IllegalArgumentException for infinity even with lenient mode");
        } catch (IllegalArgumentException e) {
            assertEquals("Numeric values must be finite, but was -Infinity", e.getMessage());
        }
    }
}
