import com.google.gson.stream.JsonWriter;
import org.junit.Before;
import org.junit.Test;

import java.io.IOException;
import java.io.StringWriter;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class JsonWriterNullValueTest {

    private StringWriter stringWriter;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() {
        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
    }

    @Test
    public void testNullValueInRoot() throws IOException {
        jsonWriter.nullValue();
        assertEquals("null", stringWriter.toString());
    }

    @Test
    public void testNullValueInArray() throws IOException {
        jsonWriter.beginArray();
        jsonWriter.nullValue();
        jsonWriter.nullValue();
        jsonWriter.endArray();
        assertEquals("[null,null]", stringWriter.toString());
    }

    @Test
    public void testNullValueInObject() throws IOException {
        jsonWriter.beginObject();
        jsonWriter.name("key1").nullValue();
        jsonWriter.name("key2").nullValue();
        jsonWriter.endObject();
        assertEquals("{\"key1\":null,\"key2\":null}", stringWriter.toString());
    }

    @Test
    public void testNullValueWithSerializeNullsTrue() throws IOException {
        jsonWriter.setSerializeNulls(true);
        jsonWriter.beginObject();
        jsonWriter.name("key").nullValue();
        jsonWriter.endObject();
        assertEquals("{\"key\":null}", stringWriter.toString());
        assertTrue(jsonWriter.getSerializeNulls());
    }

    @Test
    public void testNullValueWithSerializeNullsFalse() throws IOException {
        jsonWriter.setSerializeNulls(false);
        jsonWriter.beginObject();
        jsonWriter.name("key").nullValue();
        jsonWriter.endObject();
        assertEquals("{}", stringWriter.toString());
        assertFalse(jsonWriter.getSerializeNulls());
    }

    @Test
    public void testNullValueWithSerializeNullsFalseAndNoName() throws IOException {
        jsonWriter.setSerializeNulls(false);
        jsonWriter.nullValue(); // Should still write "null" if not part of an object with a deferred name
        assertEquals("null", stringWriter.toString());
    }

    @Test
    public void testNullValueChaining() throws IOException {
        jsonWriter.beginArray()
                .nullValue()
                .nullValue()
                .endArray();
        assertEquals("[null,null]", stringWriter.toString());
    }

    @Test
    public void testNullValueAfterOtherValues() throws IOException {
        jsonWriter.beginArray();
        jsonWriter.value("hello");
        jsonWriter.nullValue();
        jsonWriter.value(123);
        jsonWriter.nullValue();
        jsonWriter.endArray();
        assertEquals("[\"hello\",null,123,null]", stringWriter.toString());
    }

    @Test
    public void testNullValueInNestedObjectsAndArrays() throws IOException {
        jsonWriter.beginObject();
        jsonWriter.name("array").beginArray().nullValue().value(true).endArray();
        jsonWriter.name("object").beginObject().name("nestedNull").nullValue().endObject();
        jsonWriter.name("standaloneNull").nullValue();
        jsonWriter.endObject();
        assertEquals("{\"array\":[null,true],\"object\":{\"nestedNull\":null},\"standaloneNull\":null}", stringWriter.toString());
    }

    @Test
    public void testNullValueWithIndent() throws IOException {
        jsonWriter.setIndent("  ");
        jsonWriter.beginObject();
        jsonWriter.name("key").nullValue();
        jsonWriter.endObject();
        assertEquals("{\n  \"key\": null\n}", stringWriter.toString());
    }

    @Test
    public void testNullValueWithIndentAndSerializeNullsFalse() throws IOException {
        jsonWriter.setIndent("  ");
        jsonWriter.setSerializeNulls(false);
        jsonWriter.beginObject();
        jsonWriter.name("key").nullValue();
        jsonWriter.endObject();
        assertEquals("{}", stringWriter.toString());
    }
}
