    public void testRandom_noCharsProvided_startEndZero_lettersNumbersFalse() {
        // All 16-bit Unicode characters (U+0000 to U+FFFF)
        Random mockRandom = new Random() {
            private int callCount = 0;
            @Override
            public int nextInt(int bound) {
                callCount++;
                if (callCount == 1) return 0; // U+0000
                if (callCount == 2) return 65535; // U+FFFF
                if (callCount == 3) return 0xD800; // High surrogate
                if (callCount == 4) return 0xDC00; // Low surrogate (generated by the method)
                if (callCount == 5) return 0xDC00; // Low surrogate (randomly selected)
                if (callCount == 6) return 0xD800; // High surrogate (generated by the method)
                return 0;
            }
        };
        String result = RandomStringUtils.random(6, 0, 0, false, false, null, mockRandom);
        assertEquals("\u0000\uFFFF\uD800\uDC00\uDC00\uD800", result);
        assertEquals(6, result.length());
    }

    @Test
    public void testRandom_noCharsProvided_startEndZero_lettersTrue() {
        // Characters from ' ' (U+0020) to 'z' (U+007A), restricted to letters
        Random mockRandom = new Random() {
            private int callCount = 0;
            @Override
            public int nextInt(int bound) {
                callCount++;
                if (callCount == 1) return 'a' - 32; // 'a'
                if (callCount == 2) return 'Z' - 32; // 'Z'
                if (callCount == 3) return ' ' - 32; // ' ' (not a letter, should be re-rolled)
                if (callCount == 4) return 'b' - 32; // 'b'
                return 0;
            }
        };
        String result = RandomStringUtils.random(3, 0, 0, true, false, null, mockRandom);
        assertEquals("aZb", result);
        assertTrue(Character.isLetter(result.charAt(0)));
        assertTrue(Character.isLetter(result.charAt(1)));
        assertTrue(Character.isLetter(result.charAt(2)));
    }

    @Test
    public void testRandom_noCharsProvided_startEndZero_numbersTrue() {
        // Characters from ' ' (U+0020) to 'z' (U+007A), restricted to numbers
        Random mockRandom = new Random() {
            private int callCount = 0;
            @Override
            public int nextInt(int bound) {
                callCount++;
                if (callCount == 1) return '0' - 32; // '0'
                if (callCount == 2) return '9' - 32; // '9'
                if (callCount == 3) return 'a' - 32; // 'a' (not a number, should be re-rolled)
                if (callCount == 4) return '1' - 32; // '1'
                return 0;
            }
        };
