        assertEquals("091", result);
        assertTrue(Character.isDigit(result.charAt(0)));
        assertTrue(Character.isDigit(result.charAt(1)));
        assertTrue(Character.isDigit(result.charAt(2)));
    }

    @Test
    public void testRandom_noCharsProvided_startEndZero_lettersNumbersTrue() {
        // Characters from ' ' (U+0020) to 'z' (U+007A), restricted to letters or numbers
        Random mockRandom = new Random() {
            private int callCount = 0;
            @Override
            public int nextInt(int bound) {
                callCount++;
                if (callCount == 1) return 'a' - 32; // 'a'
                if (callCount == 2) return '5' - 32; // '5'
                if (callCount == 3) return ' ' - 32; // ' ' (not letter/number, should be re-rolled)
