    @Test
    public void testEquals_BothNull() {
        assertTrue(StringUtils.equals(null, null));
    }

    @Test
    public void testEquals_FirstNullSecondNonNull() {
        assertFalse(StringUtils.equals(null, "abc"));
    }

    @Test
    public void testEquals_FirstNonNullSecondNull() {
        assertFalse(StringUtils.equals("abc", null));
    }

    @Test
    public void testEquals_BothEmpty() {
        assertTrue(StringUtils.equals("", ""));
    }

    @Test
    public void testEquals_IdenticalStrings() {
        assertTrue(StringUtils.equals("abc", "abc"));
    }

    @Test
    public void testEquals_DifferentStrings() {
        assertFalse(StringUtils.equals("abc", "def"));
    }

    @Test
    public void testEquals_CaseDifference() {
        assertFalse(StringUtils.equals("abc", "ABC"));
    }

    @Test
    public void testEquals_DifferentLength() {
        assertFalse(StringUtils.equals("abc", "abcd"));
    }

    @Test
    public void testEquals_EmptyAndNonNull() {
        assertFalse(StringUtils.equals("", "abc"));
        assertFalse(StringUtils.equals("abc", ""));
    }

    @Test
    public void testEquals_CharSequenceImplementation() {
        CharSequence cs1 = new StringBuilder("hello");
        CharSequence cs2 = new StringBuilder("hello");
        assertTrue(StringUtils.equals(cs1, cs2));

        CharSequence cs3 = "world";
        CharSequence cs4 = new StringBuilder("world");
        assertTrue(StringUtils.equals(cs3, cs4));

        CharSequence cs5 = "test";
        CharSequence cs6 = "TEST";
        assertFalse(StringUtils.equals(cs5, cs6));
    }

    @Test
    public void testEquals_OneEmptyOneNull() {
        assertFalse(StringUtils.equals("", null));
        assertFalse(StringUtils.equals(null, ""));
    }

    @Test
    public void testEquals_StringsWithSpaces() {
        assertTrue(StringUtils.equals(" hello ", " hello "));
        assertFalse(StringUtils.equals(" hello", "hello "));
    }

    @Test
    public void testEquals_LongStrings() {
        String longString1 = "This is a very long string that should be compared for equality.";
        String longString2 = "This is a very long string that should be compared for equality.";
        String longString3 = "This is a very long string that should be compared for equality. Different.";
        assertTrue(StringUtils.equals(longString1, longString2));
        assertFalse(StringUtils.equals(longString1, longString3));
    }
