    public void testJoin_MultipleElements() {
        assertEquals("a,b,c", StringUtils.join(new Object[]{"a", "b", "c"}, ',', 0, 3));
    }

    @Test
    public void testJoin_MultipleElementsWithNull() {
        assertEquals("a,b,,c", StringUtils.join(new Object[]{"a", "b", null, "c"}, ',', 0, 4));
    }

