    public void testJoin_SeparatorOnly() {
        assertEquals(",,", StringUtils.join(new Object[]{null, null, null}, ',', 0, 3));
    }

    @Test
    public void testJoin_SubRange_StartAndEndInclusive() {
        assertEquals("b,c", StringUtils.join(new Object[]{"a", "b", "c", "d"}, ',', 1, 3));
    }

