import org.apache.commons.lang3.StringUtils;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtilsJoinTest {

    @Test
    public void testJoin_NullArray() {
        assertNull(StringUtils.join(null, "-", 0, 0));
    }

    @Test
    public void testJoin_EmptyArray() {
        Object[] array = {};
        assertEquals("", StringUtils.join(array, "-", 0, 0));
    }

    @Test
    public void testJoin_SingleElementArray() {
        Object[] array = {"a"};
        assertEquals("a", StringUtils.join(array, "-", 0, 1));
    }

    @Test
    public void testJoin_MultipleElements() {
        Object[] array = {"a", "b", "c"};
        assertEquals("a--b--c", StringUtils.join(array, "--", 0, 3));
    }

    @Test
    public void testJoin_MultipleElementsWithNullSeparator() {
        Object[] array = {"a", "b", "c"};
        assertEquals("abc", StringUtils.join(array, null, 0, 3));
    }

    @Test
    public void testJoin_MultipleElementsWithEmptySeparator() {
        Object[] array = {"a", "b", "c"};
        assertEquals("abc", StringUtils.join(array, "", 0, 3));
    }

    @Test
    public void testJoin_ArrayWithNullElements() {
        Object[] array = {null, "b", null, "d"};
        assertEquals("-b--d", StringUtils.join(array, "-", 0, 4));
    }

    @Test
    public void testJoin_ArrayWithEmptyStrings() {
        Object[] array = {"a", "", "c"};
        assertEquals("a--c", StringUtils.join(array, "--", 0, 3));
    }

    @Test
    public void testJoin_ArrayWithNullAndEmptyStrings() {
        Object[] array = {null, "", "a"};
        assertEquals("--a", StringUtils.join(array, "-", 0, 3));
    }

    @Test
    public void testJoin_StartIndexInclusiveEndIndexExclusive() {
        Object[] array = {"a", "b", "c", "d"};
        assertEquals("b-c", StringUtils.join(array, "-", 1, 3));
    }

    @Test
    public void testJoin_StartIndexEqualsEndIndex() {
        Object[] array = {"a", "b", "c"};
        assertEquals("", StringUtils.join(array, "-", 1, 1));
    }

    @Test
    public void testJoin_RangeWithOnlyNullElements() {
        Object[] array = {"a", null, null, "d"};
        assertEquals("", StringUtils.join(array, "-", 1, 3));
    }

    @Test
    public void testJoin_RangeWithOneNonNullElement() {
        Object[] array = {"a", null, "c", null, "e"};
        assertEquals("c", StringUtils.join(array, "-", 2, 3));
    }

    @Test
    public void testJoin_RangeAtBeginning() {
        Object[] array = {"a", "b", "c"};
        assertEquals("a-b", StringUtils.join(array, "-", 0, 2));
    }

    @Test
    public void testJoin_RangeAtEnd() {
        Object[] array = {"a", "b", "c"};
        assertEquals("b-c", StringUtils.join(array, "-", 1, 3));
    }

    @Test
    public void testJoin_NonStringObjects() {
        Object[] array = {1, 2.5, true};
        assertEquals("1-2.5-true", StringUtils.join(array, "-", 0, 3));
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testJoin_StartIndexLessThanZero() {
        Object[] array = {"a", "b"};
        StringUtils.join(array, "-", -1, 1);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testJoin_EndIndexGreaterThanArrayLength() {
        Object[] array = {"a", "b"};
        StringUtils.join(array, "-", 0, 3);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testJoin_EndIndexGreaterThanArrayLengthWithEmptyArray() {
        Object[] array = {};
        StringUtils.join(array, "-", 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testJoin_StartIndexGreaterThanEndIndex() {
        Object[] array = {"a", "b"};
        StringUtils.join(array, "-", 2, 1);
    }

    @Test
    public void testJoin_StartIndexEqualsArrayLength() {
        Object[] array = {"a", "b"};
        assertEquals("", StringUtils.join(array, "-", 2, 2));
    }

    @Test
    public void testJoin_SeparatorWithSpecialCharacters() {
        Object[] array = {"a", "b"};
        assertEquals("a###b", StringUtils.join(array, "###", 0, 2));
    }

    @Test
    public void testJoin_LargeArray() {
        Object[] array = new Object[100];
        for (int i = 0; i < 100; i++) {
            array[i] = String.valueOf(i);
        }
        StringBuilder expected = new StringBuilder();
        for (int i = 0; i < 99; i++) {
            expected.append(i).append(",");
        }
        expected.append(99);
        assertEquals(expected.toString(), StringUtils.join(array, ",", 0, 100));
    }

    @Test
