import org.apache.commons.lang3.time.DateUtils;
import org.junit.Test;
import static org.junit.Assert.*;

import java.util.Calendar;
import java.util.GregorianCalendar;
import java.util.TimeZone;

public class DateUtilsIsSameLocalTimeTest {

    @Test
    public void testIsSameLocalTime_SameTimeDifferentDate() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 30, 45);
        cal1.set(Calendar.MILLISECOND, 123);
        Calendar cal2 = new GregorianCalendar(2023, Calendar.FEBRUARY, 2, 10, 30, 45);
        cal2.set(Calendar.MILLISECOND, 123);
        assertTrue(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_SameTimeDifferentTimeZone() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 30, 45);
        cal1.set(Calendar.MILLISECOND, 123);
        cal1.setTimeZone(TimeZone.getTimeZone("GMT+01:00"));

        Calendar cal2 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 30, 45);
        cal2.set(Calendar.MILLISECOND, 123);
        cal2.setTimeZone(TimeZone.getTimeZone("GMT+02:00"));

        assertTrue(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentHour() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 30, 45);
        cal1.set(Calendar.MILLISECOND, 123);
        Calendar cal2 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 11, 30, 45);
        cal2.set(Calendar.MILLISECOND, 123);
        assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentMinute() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 30, 45);
        cal1.set(Calendar.MILLISECOND, 123);
        Calendar cal2 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 31, 45);
        cal2.set(Calendar.MILLISECOND, 123);
        assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentSecond() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 30, 45);
        cal1.set(Calendar.MILLISECOND, 123);
        Calendar cal2 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 30, 46);
        cal2.set(Calendar.MILLISECOND, 123);
        assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentMillisecond() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 30, 45);
        cal1.set(Calendar.MILLISECOND, 123);
        Calendar cal2 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 30, 45);
        cal2.set(Calendar.MILLISECOND, 124);
        assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_AllSame() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 30, 45);
        cal1.set(Calendar.MILLISECOND, 123);
        Calendar cal2 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 30, 45);
        cal2.set(Calendar.MILLISECOND, 123);
        assertTrue(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_Midnight() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 0, 0, 0);
        cal1.set(Calendar.MILLISECOND, 0);
        Calendar cal2 = new GregorianCalendar(2023, Calendar.FEBRUARY, 2, 0, 0, 0);
        cal2.set(Calendar.MILLISECOND, 0);
        assertTrue(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_AlmostMidnight() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 23, 59, 59);
        cal1.set(Calendar.MILLISECOND, 999);
        Calendar cal2 = new GregorianCalendar(2023, Calendar.FEBRUARY, 2, 23, 59, 59);
        cal2.set(Calendar.MILLISECOND, 999);
        assertTrue(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentCalendarTypes() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 30, 45);
        cal1.set(Calendar.MILLISECOND, 123);
        // Calendar.getInstance() might return a different subclass of Calendar
        Calendar cal2 = Calendar.getInstance();
        cal2.set(2023, Calendar.FEBRUARY, 2, 10, 30, 45);
        cal2.set(Calendar.MILLISECOND, 123);
        assertTrue(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIsSameLocalTime_NullCal1() {
        Calendar cal2 = new GregorianCalendar();
        DateUtils.isSameLocalTime(null, cal2);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIsSameLocalTime_NullCal2() {
        Calendar cal1 = new GregorianCalendar();
        DateUtils.isSameLocalTime(cal1, null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIsSameLocalTime_BothNull() {
        DateUtils.isSameLocalTime(null, null);
    }
}
