import org.apache.commons.lang3.math.NumberUtils;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtilsIsNumberTest {

    @Test
    public void testIsNumber_NullAndEmpty() {
        assertFalse(NumberUtils.isNumber(null));
        assertFalse(NumberUtils.isNumber(""));
        assertFalse(NumberUtils.isNumber(" ")); // Whitespace is not a number
    }

    @Test
    public void testIsNumber_StandardIntegers() {
        assertTrue(NumberUtils.isNumber("0"));
        assertTrue(NumberUtils.isNumber("123"));
        assertTrue(NumberUtils.isNumber("-45"));
        assertTrue(NumberUtils.isNumber("+67")); // Although not explicitly mentioned, common numeric parsing handles this.
        assertTrue(NumberUtils.isNumber("007"));
        assertTrue(NumberUtils.isNumber("9876543210")); // Large integer
        assertTrue(NumberUtils.isNumber("-9876543210")); // Large negative integer
    }

    @Test
    public void testIsNumber_DecimalNumbers() {
        assertTrue(NumberUtils.isNumber("1.23"));
        assertTrue(NumberUtils.isNumber("-0.5"));
        assertTrue(NumberUtils.isNumber("123."));
        assertTrue(NumberUtils.isNumber(".5"));
        assertTrue(NumberUtils.isNumber("0.0"));
        assertTrue(NumberUtils.isNumber("-1.0"));
        assertTrue(NumberUtils.isNumber("123.456789"));
        assertTrue(NumberUtils.isNumber("-123.456789"));
    }

    @Test
    public void testIsNumber_ScientificNotation() {
        assertTrue(NumberUtils.isNumber("1.2e-3"));
        assertTrue(NumberUtils.isNumber("1E+5"));
        assertTrue(NumberUtils.isNumber("1e5"));
        assertTrue(NumberUtils.isNumber("-1.2e-3"));
        assertTrue(NumberUtils.isNumber("1.23456789E10"));
        assertTrue(NumberUtils.isNumber("-1.23456789E-10"));
