        assertEquals(Integer.valueOf(2147483647), NumberUtils.createNumber("2147483647")); // Max Integer
        assertEquals(Integer.valueOf(-2147483648), NumberUtils.createNumber("-2147483648")); // Min Integer
    }

    @Test
    public void testCreateNumberLong() {
        assertEquals(Long.valueOf(2147483648L), NumberUtils.createNumber("2147483648")); // Exceeds Integer.MAX_VALUE
        assertEquals(Long.valueOf(-2147483649L), NumberUtils.createNumber("-2147483649")); // Exceeds Integer.MIN_VALUE
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123L"));
        assertEquals(Long.valueOf(-45L), NumberUtils.createNumber("-45l"));
        assertEquals(Long.valueOf(0L), NumberUtils.createNumber("0L"));
        assertEquals(Long.valueOf(9223372036854775807L), NumberUtils.createNumber("9223372036854775807L")); // Max Long
        assertEquals(Long.valueOf(-9223372036854775808L), NumberUtils.createNumber("-9223372036854775808L")); // Min Long
    }

