        assertEquals(new BigInteger("9223372036854775808"), NumberUtils.createNumber("9223372036854775808")); // Exceeds Long.MAX_VALUE
        assertEquals(new BigInteger("-9223372036854775809"), NumberUtils.createNumber("-9223372036854775809")); // Exceeds Long.MIN_VALUE
        assertEquals(new BigInteger("1000000000000000000000"), NumberUtils.createNumber("1000000000000000000000"));
    }

    @Test
    public void testCreateNumberFloat() {
        assertEquals(Float.valueOf(1.23f), NumberUtils.createNumber("1.23f"));
        assertEquals(Float.valueOf(-0.5f), NumberUtils.createNumber("-0.5F"));
        assertEquals(Float.valueOf(0.0f), NumberUtils.createNumber("0.0f"));
        assertEquals(Float.valueOf(123.0f), NumberUtils.createNumber("123.f"));
        assertEquals(Float.valueOf(Float.MAX_VALUE), NumberUtils.createNumber(Float.MAX_VALUE + "f"));
        assertEquals(Float.valueOf(Float.MIN_VALUE), NumberUtils.createNumber(Float.MIN_VALUE + "f"));
        assertEquals(Float.valueOf(Float.POSITIVE_INFINITY), NumberUtils.createNumber("1e40f")); // Infinity
        assertEquals(Float.valueOf(Float.NEGATIVE_INFINITY), NumberUtils.createNumber("-1e40f")); // Negative Infinity
    }

