        assertEquals(Double.valueOf(123.0), NumberUtils.createNumber("123."));
        assertEquals(Double.valueOf(1.23d), NumberUtils.createNumber("1.23d"));
        assertEquals(Double.valueOf(-0.5D), NumberUtils.createNumber("-0.5D"));
