        assertEquals(new BigDecimal("-1.23456789012345678901234567890123456789"), NumberUtils.createNumber("-1.23456789012345678901234567890123456789"));
        assertEquals(new BigDecimal("1.23456789012345678901234567890123456789e-100"), NumberUtils.createNumber("1.23456789012345678901234567890123456789e-100"));
    }

    @Test
    public void testCreateNumberScientificNotation() {
