        assertEquals(new BigDecimal("1.23456789012345678901234567890123456789e309"), NumberUtils.createNumber("1.23456789012345678901234567890123456789e309"));

        // This number is too small for float, but not for double
        assertEquals(Double.valueOf("1.2345678901234567e-40"), NumberUtils.createNumber("1.2345678901234567e-40"));

