        assertEquals(Double.valueOf(.5), NumberUtils.createNumber(".5"));
        assertEquals(Double.valueOf(-.5), NumberUtils.createNumber("-.5"));
        assertEquals(Float.valueOf(.5f), NumberUtils.createNumber(".5f"));
