        char[] searchChars = {'x', 'a'};
        assertFalse(StringUtils.containsNone(cs, searchChars));
    }

    @Test
    public void testContainsNone_MiddleCharMatch() {
        CharSequence cs = "orange";
        char[] searchChars = {'x', 'a', 'y'};
        assertFalse(StringUtils.containsNone(cs, searchChars));
    }

