import org.apache.commons.lang3.StringUtils;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtilsContainsAnyTest {

    @Test
    public void testContainsAny() {
        // Test case 1: cs is null
        assertFalse(StringUtils.containsAny(null, new char[]{'a', 'b'}));

        // Test case 2: cs is empty
        assertFalse(StringUtils.containsAny("", new char[]{'a', 'b'}));

        // Test case 3: searchChars is null
        assertFalse(StringUtils.containsAny("abc", null));

        // Test case 4: searchChars is empty
        assertFalse(StringUtils.containsAny("abc", new char[]{}));

        // Test case 5: cs contains one of the searchChars
        assertTrue(StringUtils.containsAny("abc", new char[]{'a', 'x'}));

        // Test case 6: cs contains none of the searchChars
        assertFalse(StringUtils.containsAny("abc", new char[]{'x', 'y'}));

        // Test case 7: cs contains multiple of the searchChars
        assertTrue(StringUtils.containsAny("ab", new char[]{'a', 'b'}));

        // Test case 8: cs contains a character that is also in searchChars, but not at the beginning
        assertTrue(StringUtils.containsAny("zzabyycdxx", new char[]{'z', 'a'}));

        // Test case 9: cs contains a character that is also in searchChars, but not at the beginning
        assertTrue(StringUtils.containsAny("zzabyycdxx", new char[]{'b', 'y'}));

        // Test case 10: cs does not contain any of the searchChars
        assertFalse(StringUtils.containsAny("aba", new char[]{'z'}));

        // Test case 11: cs is a single character, searchChars contains it
        assertTrue(StringUtils.containsAny("a", new char[]{'a'}));

        // Test case 12: cs is a single character, searchChars does not contain it
        assertFalse(StringUtils.containsAny("a", new char[]{'b'}));

        // Test case 13: cs is longer than searchChars, and contains one
        assertTrue(StringUtils.containsAny("hello", new char[]{'o'}));

        // Test case 14: cs is longer than searchChars, and contains none
        assertFalse(StringUtils.containsAny("hello", new char[]{'x', 'y', 'z'}));

        // Test case 15: searchChars is longer than cs, and cs contains one
        assertTrue(StringUtils.containsAny("a", new char[]{'x', 'y', 'a'}));

        // Test case 16: searchChars is longer than cs, and cs contains none
        assertFalse(StringUtils.containsAny("a", new char[]{'x', 'y', 'z'}));

        // Test case 17: cs and searchChars are both empty (covered by test case 2 and 4, but good to be explicit)
        assertFalse(StringUtils.containsAny("", new char[]{}));

        // Test case 18: cs contains a character that is the same as a searchChar, case sensitive
        assertTrue(StringUtils.containsAny("ABC", new char[]{'A'}));
        assertFalse(StringUtils.containsAny("ABC", new char[]{'a'}));

        // Test case 19: cs with special characters
        assertTrue(StringUtils.containsAny("!@#$", new char[]{'@'}));
        assertFalse(StringUtils.containsAny("!@#$", new char[]{'%'}));

        // Test case 20: cs with numbers
        assertTrue(StringUtils.containsAny("12345", new char[]{'3'}));
        assertFalse(StringUtils.containsAny("12345", new char[]{'6'}));
    }
}
