import org.junit.Test;
import static org.junit.Assert.*;

import org.apache.commons.lang3.ArrayUtils;
import java.util.Arrays;
import java.util.List;
import java.io.Serializable;

public class ArrayUtilsAddTest {

    @Test
    public void testAddToArrayWithNonNullElement() {
        String[] array = {"a", "b"};
        String element = "c";
        String[] expected = {"a", "b", "c"};
        String[] result = ArrayUtils.add(array, element);
        assertArrayEquals(expected, result);
        // Ensure original array is unchanged
        assertArrayEquals(new String[]{"a", "b"}, array);
    }

    @Test
    public void testAddToArrayWithNullElement() {
        String[] array = {"a", "b"};
        String element = null;
        String[] expected = {"a", "b", null};
        String[] result = ArrayUtils.add(array, element);
        assertArrayEquals(expected, result);
        // Ensure original array is unchanged
        assertArrayEquals(new String[]{"a", "b"}, array);
    }

    @Test
    public void testAddNullToArrayWithNonNullElement() {
        String[] array = null;
        String element = "a";
        String[] expected = {"a"};
        String[] result = ArrayUtils.add(array, element);
        assertArrayEquals(expected, result);
    }

    @Test
    public void testAddNullToArrayWithNullElement() {
        // This case should throw IllegalArgumentException
        String[] array = null;
        String element = null;
        try {
            ArrayUtils.add(array, element);
            fail("IllegalArgumentException was expected for null array and null element.");
        } catch (IllegalArgumentException e) {
            assertEquals("Array and element cannot both be null.", e.getMessage());
        }
    }

    @Test
    public void testAddEmptyArrayWithNonNullElement() {
        String[] array = {};
        String element = "a";
        String[] expected = {"a"};
        String[] result = ArrayUtils.add(array, element);
        assertArrayEquals(expected, result);
        // Ensure original array is unchanged
        assertArrayEquals(new String[]{}, array);
    }

    @Test
    public void testAddEmptyArrayWithNullElement() {
        String[] array = {};
        String element = null;
        String[] expected = {null};
        String[] result = ArrayUtils.add(array, element);
        assertArrayEquals(expected, result);
        // Ensure original array is unchanged
        assertArrayEquals(new String[]{}, array);
    }

    @Test
    public void testAddWithDifferentTypeElement() {
        Integer[] array = {1, 2};
        // Adding a String to an Integer array should result in ArrayStoreException
        try {
            ArrayUtils.add(array, (Integer) null); // This is to satisfy the generic type, but the test is about type mismatch
            // The Javadoc for the generic add method doesn't explicitly mention ArrayStoreException for type mismatch
            // when the array is not null. However, the underlying array copy mechanism would throw it.
            // Let's test with an element that is clearly not assignable.
            // This specific overload of add is for T[], T, so the compiler will enforce T.
            // To test ArrayStoreException, we need to consider a scenario where the type inference
            // allows it but runtime assignment fails, which is harder with generics.
            // The docstring for the method under test states:
            // "@throws ArrayStoreException if the type of the {@code element} is not assignable to the
            // component type of the {@code array} (when {@code array} is not {@code null})."
            // This implies that if T is Object, and we try to add a String to an Integer[], it should fail.
            // However, the signature <T> T[] add(T[] array, T element) prevents this at compile time.
            // Let's assume T is Object for this test to simulate the scenario.
            Object[] objArray = new Integer[]{1, 2};
            Object stringElement = "3";
            ArrayUtils.add(objArray, stringElement);
            fail("ArrayStoreException was expected for adding incompatible type element.");
        } catch (ArrayStoreException e) {
            // Expected
            assertTrue(e.getMessage().contains("java.lang.String cannot be stored in an array of type java.lang.Integer"));
        }
    }

    @Test
    public void testAddNullArrayWithInterfaceElement() {
