import org.apache.commons.lang3.math.NumberUtils;
import org.junit.Test;
import static org.junit.Assert.*;

import java.math.BigDecimal;
import java.math.BigInteger;

public class NumberUtilsCreateNumberTest {

    @Test
    public void testCreateNumberNull() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test
    public void testCreateNumberInteger() {
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
        assertEquals(Integer.valueOf(-456), NumberUtils.createNumber("-456"));
        assertEquals(Integer.valueOf(0), NumberUtils.createNumber("0"));
        assertEquals(Integer.valueOf(2147483647), NumberUtils.createNumber("2147483647")); // Max Integer
        assertEquals(Integer.valueOf(-2147483648), NumberUtils.createNumber("-2147483648")); // Min Integer
    }

    @Test
    public void testCreateNumberLong() {
        assertEquals(Long.valueOf(1234567890123L), NumberUtils.createNumber("1234567890123"));
        assertEquals(Long.valueOf(-9876543210987L), NumberUtils.createNumber("-9876543210987"));
        assertEquals(Long.valueOf(2147483648L), NumberUtils.createNumber("2147483648")); // Exceeds Integer.MAX_VALUE
        assertEquals(Long.valueOf(-2147483649L), NumberUtils.createNumber("-2147483649")); // Exceeds Integer.MIN_VALUE
        assertEquals(Long.valueOf(9223372036854775807L), NumberUtils.createNumber("9223372036854775807")); // Max Long
        assertEquals(Long.valueOf(-9223372036854775808L), NumberUtils.createNumber("-9223372036854775808")); // Min Long
    }

    @Test
    public void testCreateNumberFloat() {
        assertEquals(Float.valueOf(1.23f), NumberUtils.createNumber("1.23f"));
        assertEquals(Float.valueOf(-4.56F), NumberUtils.createNumber("-4.56F"));
        assertEquals(Float.valueOf(0.0f), NumberUtils.createNumber("0.0f"));
        assertEquals(Float.valueOf(Float.MAX_VALUE), NumberUtils.createNumber("3.4028235e+38f"));
        assertEquals(Float.valueOf(Float.MIN_VALUE), NumberUtils.createNumber("1.4e-45f"));
        assertEquals(Float.valueOf(Float.POSITIVE_INFINITY), NumberUtils.createNumber("Infinityf"));
        assertEquals(Float.valueOf(Float.NEGATIVE_INFINITY), NumberUtils.createNumber("-Infinityf"));
        assertTrue(Float.isNaN((Float) NumberUtils.createNumber("NaNf")));
    }

    @Test
    public void testCreateNumberDouble() {
        assertEquals(Double.valueOf(1.23d), NumberUtils.createNumber("1.23d"));
        assertEquals(Double.valueOf(-4.56D), NumberUtils.createNumber("-4.56D"));
        assertEquals(Double.valueOf(0.0d), NumberUtils.createNumber("0.0d"));
        assertEquals(Double.valueOf(1.23), NumberUtils.createNumber("1.23")); // No type specifier, decimal point
        assertEquals(Double.valueOf(Double.MAX_VALUE), NumberUtils.createNumber("1.7976931348623157e+308d"));
        assertEquals(Double.valueOf(Double.MIN_VALUE), NumberUtils.createNumber("4.9e-324d"));
        assertEquals(Double.valueOf(Double.POSITIVE_INFINITY), NumberUtils.createNumber("Infinityd"));
        assertEquals(Double.valueOf(Double.NEGATIVE_INFINITY), NumberUtils.createNumber("-Infinityd"));
        assertTrue(Double.isNaN((Double) NumberUtils.createNumber("NaND")));
    }

    @Test
    public void testCreateNumberBigInteger() {
        assertEquals(new BigInteger("9223372036854775808"), NumberUtils.createNumber("9223372036854775808")); // Exceeds Long.MAX_VALUE
        assertEquals(new BigInteger("-9223372036854775809"), NumberUtils.createNumber("-9223372036854775809")); // Exceeds Long.MIN_VALUE
        assertEquals(new BigInteger("100000000000000000000000000000000000000000000000000"), NumberUtils.createNumber("100000000000000000000000000000000000000000000000000"));
    }

