        assertTrue(StringUtils.containsIgnoreCase("HelloWorld", "hello"));
        assertTrue(StringUtils.containsIgnoreCase("HelloWorld", "WORLD"));
        assertTrue(StringUtils.containsIgnoreCase("HelloWorld", "hElLoWoRlD"));

        // Partial match, different cases
        assertTrue(StringUtils.containsIgnoreCase("Programming", "gram"));
        assertTrue(StringUtils.containsIgnoreCase("Programming", "GRAM"));
        assertTrue(StringUtils.containsIgnoreCase("Programming", "gRaM"));

