        assertTrue(StringUtils.containsIgnoreCase("!@#$", "@#"));
        assertFalse(StringUtils.containsIgnoreCase("!@#$", "%^"));

        // String with numbers
        assertTrue(StringUtils.containsIgnoreCase("12345", "23"));
        assertFalse(StringUtils.containsIgnoreCase("12345", "67"));

        // Longer strings
