        assertTrue(StringUtils.containsIgnoreCase("This is a long sentence for testing purposes.", "PURPOSES"));
        assertFalse(StringUtils.containsIgnoreCase("This is a long sentence for testing purposes.", "nonexistent"));

        // Search string longer than the main string
        assertFalse(StringUtils.containsIgnoreCase("short", "longerstring"));
        assertFalse(StringUtils.containsIgnoreCase("a", "AA"));

        // Case variations at boundaries
        assertTrue(StringUtils.containsIgnoreCase("ABC", "a"));
        assertTrue(StringUtils.containsIgnoreCase("ABC", "C"));
        assertTrue(StringUtils.containsIgnoreCase("abc", "A"));
        assertTrue(StringUtils.containsIgnoreCase("abc", "C"));

