import org.apache.commons.lang.StringEscapeUtils;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringEscapeUtilsEscapeJavaTest {

    @Test
    public void testEscapeJava_NullInput() {
        assertNull(StringEscapeUtils.escapeJava(null));
    }

    @Test
    public void testEscapeJava_EmptyString() {
        assertEquals("", StringEscapeUtils.escapeJava(""));
    }

    @Test
    public void testEscapeJava_NoSpecialCharacters() {
        assertEquals("hello world", StringEscapeUtils.escapeJava("hello world"));
        assertEquals("12345", StringEscapeUtils.escapeJava("12345"));
        assertEquals("abcABC", StringEscapeUtils.escapeJava("abcABC"));
    }

    @Test
    public void testEscapeJava_DoubleQuote() {
        assertEquals("hello \\\"world\\\"", StringEscapeUtils.escapeJava("hello \"world\""));
        assertEquals("\\\"", StringEscapeUtils.escapeJava("\""));
        assertEquals("abc\\\"def", StringEscapeUtils.escapeJava("abc\"def"));
    }

    @Test
    public void testEscapeJava_Backslash() {
        assertEquals("hello \\\\world", StringEscapeUtils.escapeJava("hello \\world"));
        assertEquals("\\\\", StringEscapeUtils.escapeJava("\\"));
        assertEquals("abc\\\\def", StringEscapeUtils.escapeJava("abc\\def"));
    }

    @Test
    public void testEscapeJava_ControlCharacters() {
        assertEquals("line1\\nline2", StringEscapeUtils.escapeJava("line1\nline2"));
        assertEquals("tab\\tseparated", StringEscapeUtils.escapeJava("tab\tseparated"));
        assertEquals("carriage\\rreturn", StringEscapeUtils.escapeJava("carriage\rreturn"));
        assertEquals("form\\ffeed", StringEscapeUtils.escapeJava("form\ffeed"));
        assertEquals("back\\bspace", StringEscapeUtils.escapeJava("back\bspace"));
        assertEquals("\\n\\t\\r\\f\\b", StringEscapeUtils.escapeJava("\n\t\r\f\b"));
    }

    @Test
    public void testEscapeJava_MixedSpecialCharacters() {
        assertEquals("He didn't say, \\\"Stop!\\\"\\n", StringEscapeUtils.escapeJava("He didn't say, \"Stop!\"\n"));
        assertEquals("C:\\\\Program Files\\\\Java\\n", StringEscapeUtils.escapeJava("C:\\Program Files\\Java\n"));
        assertEquals("String with \\\"quotes\\\" and a \\\\backslash\\\\ and a \\nnewline.",
                StringEscapeUtils.escapeJava("String with \"quotes\" and a \\backslash\\ and a \nnewline."));
    }

    @Test
    public void testEscapeJava_UnicodeCharacters() {
        // Basic Multilingual Plane (BMP) characters
        assertEquals("\\u00E9", StringEscapeUtils.escapeJava("é")); // e acute
        assertEquals("\\u00A9", StringEscapeUtils.escapeJava("©")); // copyright symbol
        assertEquals("Hello \\u4E16\\u754C", StringEscapeUtils.escapeJava("Hello 世界")); // Chinese characters

        // Supplementary characters (outside BMP)
        assertEquals("\\uD83D\\uDE00", StringEscapeUtils.escapeJava("😀")); // Grinning Face emoji
        assertEquals("\\uD83C\\uDF08", StringEscapeUtils.escapeJava("🌈")); // Rainbow emoji
        assertEquals("Test \\uD83D\\uDE00 \\uD83C\\uDF08", StringEscapeUtils.escapeJava("Test 😀 🌈"));
    }

    @Test
    public void testEscapeJava_SingleQuotesNotEscaped() {
        assertEquals("It's a test", StringEscapeUtils.escapeJava("It's a test"));
        assertEquals("'", StringEscapeUtils.escapeJava("'"));
        assertEquals("abc'def", StringEscapeUtils.escapeJava("abc'def"));
    }

    @Test
    public void testEscapeJava_AllControlCharacters() {
        String input = "\u0000\u0001\u0002\u0003\u0004\u0005\u0006\u0007\b\t\n\u000B\f\r\u000E\u000F" +
                       "\u0010\u0011\u0012\u0013\u0014\u0015\u0016\u0017\u0018\u0019\u001A\u001B\u001C\u001D\u001E\u001F";
        String expected = "\\u0000\\u0001\\u0002\\u0003\\u0004\\u0005\\u0006\\u0007\\b\\t\\n\\u000B\\f\\r\\u000E\\u000F" +
                          "\\u0010\\u0011\\u0012\\u0013\\u0014\\u0015\\u0016\\u0017\\u0018\\u0019\\u001A\\u001B\\u001C\\u001D\\u001E\\u001F";
        assertEquals(expected, StringEscapeUtils.escapeJava(input));
    }

    @Test
    public void testEscapeJava_EdgeCases() {
        assertEquals("\\\"\\\\\\n\\t\\r\\f\\b\\u0000", StringEscapeUtils.escapeJava("\"\\\n\t\r\f\b\u0000"));
        assertEquals("A\\u0000B", StringEscapeUtils.escapeJava("A\u0000B"));
        assertEquals("A\\u001FB", StringEscapeUtils.escapeJava("A\u001FB"));
    }
}
