import org.apache.commons.lang.BooleanUtils;
import org.junit.Test;
import static org.junit.Assert.*;

public class BooleanUtilsToBooleanStringTest {

    @Test
    public void testToBooleanTruthyStrings() {
        // Test "true" variations
        assertTrue(BooleanUtils.toBoolean("true"));
        assertTrue(BooleanUtils.toBoolean("TRUE"));
        assertTrue(BooleanUtils.toBoolean("True"));
        assertTrue(BooleanUtils.toBoolean("tRUE"));
        assertTrue(BooleanUtils.toBoolean("TrUe")); // Mixed case

        // Test "on" variations
        assertTrue(BooleanUtils.toBoolean("on"));
        assertTrue(BooleanUtils.toBoolean("ON"));
        assertTrue(BooleanUtils.toBoolean("On"));
        assertTrue(BooleanUtils.toBoolean("oN"));

        // Test "yes" variations
        assertTrue(BooleanUtils.toBoolean("yes"));
        assertTrue(BooleanUtils.toBoolean("YES"));
        assertTrue(BooleanUtils.toBoolean("Yes"));
        assertTrue(BooleanUtils.toBoolean("yEs"));
    }

    @Test
    public void testToBooleanFalseyStrings() {
        // Test null input
        assertFalse(BooleanUtils.toBoolean(null));

        // Test empty string
        assertFalse(BooleanUtils.toBoolean(""));

        // Test common false strings
        assertFalse(BooleanUtils.toBoolean("false"));
        assertFalse(BooleanUtils.toBoolean("FALSE"));
        assertFalse(BooleanUtils.toBoolean("False"));
        assertFalse(BooleanUtils.toBoolean("fAlSe"));

        // Test other non-truthy strings
        assertFalse(BooleanUtils.toBoolean("off"));
        assertFalse(BooleanUtils.toBoolean("no"));
        assertFalse(BooleanUtils.toBoolean("0"));
        assertFalse(BooleanUtils.toBoolean("1"));
        assertFalse(BooleanUtils.toBoolean("abc"));
        assertFalse(BooleanUtils.toBoolean(" true")); // Leading space
        assertFalse(BooleanUtils.toBoolean("true ")); // Trailing space
        assertFalse(BooleanUtils.toBoolean(" true ")); // Both spaces
        assertFalse(BooleanUtils.toBoolean("trueX")); // Suffix
        assertFalse(BooleanUtils.toBoolean("Xtrue")); // Prefix
        assertFalse(BooleanUtils.toBoolean("t r u e")); // Spaces in between
    }

    @Test
    public void testToBooleanEdgeCases() {
        // Test very long non-truthy string
        assertFalse(BooleanUtils.toBoolean("thisisareallylongstringthatshoulddefinitelybeconsideredfalse"));

        // Test string with only spaces
        assertFalse(BooleanUtils.toBoolean("   "));
    }
}
