import org.apache.commons.lang.math.NumberUtils;
import org.junit.Test;
import java.math.BigDecimal;
import java.math.BigInteger;

import static org.junit.Assert.*;

public class NumberUtilsCreateNumberTest {

    @Test
    public void testCreateNumber_NullInput() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_EmptyString() {
        NumberUtils.createNumber("");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_BlankString() {
        NumberUtils.createNumber("   ");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidFormat() {
        NumberUtils.createNumber("abc");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_DoubleDash() {
        NumberUtils.createNumber("--123");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidHex() {
        NumberUtils.createNumber("0xG");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidFloatSuffix() {
        NumberUtils.createNumber("1.23x");
    }

    @Test
    public void testCreateNumber_Integer() {
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
        assertEquals(Integer.valueOf(-45), NumberUtils.createNumber("-45"));
        assertEquals(Integer.valueOf(0), NumberUtils.createNumber("0"));
        assertEquals(Integer.valueOf(Integer.MAX_VALUE), NumberUtils.createNumber(String.valueOf(Integer.MAX_VALUE)));
        assertEquals(Integer.valueOf(Integer.MIN_VALUE), NumberUtils.createNumber(String.valueOf(Integer.MIN_VALUE)));
    }

    @Test
    public void testCreateNumber_Long() {
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123L"));
        assertEquals(Long.valueOf(-45L), NumberUtils.createNumber("-45l"));
        assertEquals(Long.valueOf(0L), NumberUtils.createNumber("0L"));
        assertEquals(Long.valueOf(Integer.MAX_VALUE + 1L), NumberUtils.createNumber(String.valueOf(Integer.MAX_VALUE + 1L)));
        assertEquals(Long.valueOf(Long.MAX_VALUE), NumberUtils.createNumber(String.valueOf(Long.MAX_VALUE)));
        assertEquals(Long.valueOf(Long.MIN_VALUE), NumberUtils.createNumber(String.valueOf(Long.MIN_VALUE)));
    }

    @Test
    public void testCreateNumber_BigInteger() {
        String bigIntStr = "9223372036854775808"; // Long.MAX_VALUE + 1
        assertEquals(new BigInteger(bigIntStr), NumberUtils.createNumber(bigIntStr));
        String negativeBigIntStr = "-9223372036854775809"; // Long.MIN_VALUE - 1
        assertEquals(new BigInteger(negativeBigIntStr), NumberUtils.createNumber(negativeBigIntStr));
    }

    @Test
    public void testCreateNumber_Float() {
        assertEquals(Float.valueOf(1.23f), NumberUtils.createNumber("1.23F"));
        assertEquals(Float.valueOf(-4.5e-2f), NumberUtils.createNumber("-4.5e-2f"));
        assertEquals(Float.valueOf(0.0f), NumberUtils.createNumber("0.0F"));
        assertEquals(Float.valueOf(Float.MAX_VALUE), NumberUtils.createNumber(String.valueOf(Float.MAX_VALUE) + "f"));
        assertEquals(Float.valueOf(Float.MIN_VALUE), NumberUtils.createNumber(String.valueOf(Float.MIN_VALUE) + "f"));
    }

    @Test
    public void testCreateNumber_Double() {
        assertEquals(Double.valueOf(1.23), NumberUtils.createNumber("1.23"));
        assertEquals(Double.valueOf(-4.5e-2), NumberUtils.createNumber("-4.5e-2"));
        assertEquals(Double.valueOf(0.0), NumberUtils.createNumber("0.0"));
        assertEquals(Double.valueOf(1.23d), NumberUtils.createNumber("1.23D"));
        assertEquals(Double.valueOf(-4.5e-2d), NumberUtils.createNumber("-4.5e-2d"));
        assertEquals(Double.valueOf(Double.MAX_VALUE), NumberUtils.createNumber(String.valueOf(Double.MAX_VALUE)));
        assertEquals(Double.valueOf(Double.MIN_VALUE), NumberUtils.createNumber(String.valueOf(Double.MIN_VALUE)));
    }

    @Test
    public void testCreateNumber_BigDecimal() {
        String bigDecimalStr = "12345678901234567890.12345678901234567890";
        assertEquals(new BigDecimal(bigDecimalStr), NumberUtils.createNumber(bigDecimalStr));
        String bigDecimalExponentStr = "1.23456789012345678901234567890E+30";
        assertEquals(new BigDecimal(bigDecimalExponentStr), NumberUtils.createNumber(bigDecimalExponentStr));
        String bigDecimalFloatOverflow = "1.0e+40f"; // Too large for float, should be double
        assertEquals(Double.valueOf(1.0e+40), NumberUtils.createNumber(bigDecimalFloatOverflow));
        String bigDecimalDoubleOverflow = "1.0e+309d"; // Too large for double, should be BigDecimal
        assertEquals(new BigDecimal("1.0e+309"), NumberUtils.createNumber(bigDecimalDoubleOverflow));
    }

    @Test
    public void testCreateNumber_Hexadecimal() {
        assertEquals(Integer.valueOf(175), NumberUtils.createNumber("0xAF"));
        assertEquals(Integer.valueOf(-16), NumberUtils.createNumber("-0x10"));
        assertEquals(Long.valueOf(255L), NumberUtils.createNumber("0xFFL"));
        assertEquals(new BigInteger("10000000000000000", 16), NumberUtils.createNumber("0x10000000000000000")); // Larger than Long
    }

    @Test
    public void testCreateNumber_LeadingZeros() {
        // Leading zeros do not imply octal
        assertEquals(Integer.valueOf(10), NumberUtils.createNumber("010"));
        assertEquals(Long.valueOf(10L), NumberUtils.createNumber("010L"));
        assertEquals(Double.valueOf(10.0), NumberUtils.createNumber("010.0"));
    }

    @Test
    public void testCreateNumber_FloatPrecision() {
        // A number that cannot be exactly represented by float, should become Double
        assertEquals(Double.valueOf(0.1), NumberUtils.createNumber("0.1"));
        assertNotEquals(Float.valueOf(0.1f), NumberUtils.createNumber("0.1")); // Demonstrates float precision issue
        // A number that can be exactly represented by float
        assertEquals(Float.valueOf(0.5f), NumberUtils.createNumber("0.5f"));
    }

    @Test
    public void testCreateNumber_DoublePrecision() {
        // A number that cannot be exactly represented by double, should become BigDecimal
        String preciseDecimal = "0.1234567890123456789"; // More precision than double
        assertEquals(new BigDecimal(preciseDecimal), NumberUtils.createNumber(preciseDecimal));
        assertNotEquals(Double.valueOf(preciseDecimal), NumberUtils.createNumber(preciseDecimal));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidFloatSuffixValue() {
        // Value too large for float, but explicitly suffixed with 'f'
        NumberUtils.createNumber("1.0e+40f");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidLongSuffixValue() {
        // Value too large for long, but explicitly suffixed with 'l'
        NumberUtils.createNumber("9223372036854775808L"); // Long.MAX_VALUE + 1
    }

    @Test
    public void testCreateNumber_NegativeZero() {
        assertEquals(Double.valueOf(-0.0), NumberUtils.createNumber("-0.0"));
        assertEquals(Float.valueOf(-0.0f), NumberUtils.createNumber("-0.0f"));
    }

    @Test
    public void testCreateNumber_ExponentWithoutDecimal() {
        assertEquals(Double.valueOf(100.0), NumberUtils.createNumber("1e2"));
        assertEquals(Float.valueOf(100.0f), NumberUtils.createNumber("1e2f"));
        assertEquals(Double.valueOf(1000.0), NumberUtils.createNumber("1000e0"));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidCharacter() {
        NumberUtils.createNumber("123a");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidDecimalPoint() {
        NumberUtils.createNumber("1.2.3");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidExponent() {
        NumberUtils.createNumber("1e");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidSignPlacement() {
        NumberUtils.createNumber("1-2");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_NegativeHex() {
        NumberUtils.createNumber("-0x");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_HexWithDecimal() {
        NumberUtils.createNumber("0x1.0");
    }
}
