import org.apache.commons.lang.text.StrBuilder;
import org.junit.Test;
import static org.junit.Assert.*;

public class StrBuilderIndexOfCharIntTest {

    @Test
    public void testIndexOfCharInt_CharFoundFromStart() {
        StrBuilder sb = new StrBuilder("abcde");
        assertEquals(0, sb.indexOf('a', 0));
        assertEquals(1, sb.indexOf('b', 0));
        assertEquals(4, sb.indexOf('e', 0));
    }

    @Test
    public void testIndexOfCharInt_CharFoundFromMiddle() {
        StrBuilder sb = new StrBuilder("abcde");
        assertEquals(2, sb.indexOf('c', 1));
        assertEquals(3, sb.indexOf('d', 2));
        assertEquals(4, sb.indexOf('e', 3));
    }

    @Test
    public void testIndexOfCharInt_CharNotFound() {
        StrBuilder sb = new StrBuilder("abcde");
        assertEquals(-1, sb.indexOf('f', 0));
        assertEquals(-1, sb.indexOf('a', 1));
        assertEquals(-1, sb.indexOf('z', 2));
    }

    @Test
    public void testIndexOfCharInt_EmptyStrBuilder() {
        StrBuilder sb = new StrBuilder("");
        assertEquals(-1, sb.indexOf('a', 0));
        assertEquals(-1, sb.indexOf('b', 5));
    }

    @Test
    public void testIndexOfCharInt_NegativeStartIndex() {
        StrBuilder sb = new StrBuilder("abcde");
        assertEquals(0, sb.indexOf('a', -1));
        assertEquals(1, sb.indexOf('b', -5));
        assertEquals(4, sb.indexOf('e', -100));
        assertEquals(-1, sb.indexOf('f', -1));
    }

    @Test
    public void testIndexOfCharInt_StartIndexGreaterThanLength() {
        StrBuilder sb = new StrBuilder("abcde");
        assertEquals(-1, sb.indexOf('a', 5));
        assertEquals(-1, sb.indexOf('b', 10));
        assertEquals(-1, sb.indexOf('e', 5));
        assertEquals(-1, sb.indexOf('f', 6));
    }

    @Test
    public void testIndexOfCharInt_StartIndexEqualToLength() {
        StrBuilder sb = new StrBuilder("abcde");
        assertEquals(-1, sb.indexOf('a', 5));
        assertEquals(-1, sb.indexOf('e', 5));
    }

    @Test
    public void testIndexOfCharInt_CharFoundAtStartIndex() {
        StrBuilder sb = new StrBuilder("abcde");
        assertEquals(0, sb.indexOf('a', 0));
        assertEquals(1, sb.indexOf('b', 1));
        assertEquals(4, sb.indexOf('e', 4));
    }

    @Test
    public void testIndexOfCharInt_MultipleOccurrences() {
        StrBuilder sb = new StrBuilder("ababa");
        assertEquals(0, sb.indexOf('a', 0));
        assertEquals(2, sb.indexOf('a', 1));
        assertEquals(2, sb.indexOf('a', 2));
        assertEquals(4, sb.indexOf('a', 3));
        assertEquals(4, sb.indexOf('a', 4));
        assertEquals(-1, sb.indexOf('a', 5));

        assertEquals(1, sb.indexOf('b', 0));
        assertEquals(1, sb.indexOf('b', 1));
        assertEquals(3, sb.indexOf('b', 2));
        assertEquals(3, sb.indexOf('b', 3));
        assertEquals(-1, sb.indexOf('b', 4));
    }

    @Test
    public void testIndexOfCharInt_SingleCharStrBuilder() {
        StrBuilder sb = new StrBuilder("x");
        assertEquals(0, sb.indexOf('x', 0));
        assertEquals(-1, sb.indexOf('x', 1));
        assertEquals(-1, sb.indexOf('y', 0));
    }

    @Test
    public void testIndexOfCharInt_NullStrBuilder() {
        // StrBuilder cannot be null, testing with an empty builder
        StrBuilder sb = new StrBuilder();
        assertEquals(-1, sb.indexOf('a', 0));
    }

    @Test
    public void testIndexOfCharInt_LargeStartIndex() {
        StrBuilder sb = new StrBuilder("abcdefg");
        assertEquals(-1, sb.indexOf('a', 100));
        assertEquals(-1, sb.indexOf('g', 100));
    }

    @Test
    public void testIndexOfCharInt_CharNotFoundAfterStartIndex() {
        StrBuilder sb = new StrBuilder("apple");
        assertEquals(-1, sb.indexOf('p', 3)); // 'p' exists, but not after index 3
        assertEquals(0, sb.indexOf('a', 0));
        assertEquals(1, sb.indexOf('p', 0));
        assertEquals(2, sb.indexOf('p', 2));
    }

    @Test
    public void testIndexOfCharInt_SpecialCharacters() {
        StrBuilder sb = new StrBuilder("!@#$%^&*()");
        assertEquals(0, sb.indexOf('!', 0));
        assertEquals(4, sb.indexOf('%', 0));
        assertEquals(9, sb.indexOf(')', 0));
        assertEquals(5, sb.indexOf('^', 3));
        assertEquals(-1, sb.indexOf('+', 0));
    }
}
