import org.apache.commons.lang.text.StrBuilder;
import org.junit.Test;
import static org.junit.Assert.*;

public class StrBuilderContainsCharTest {

    @Test
    public void testContainsChar_emptyBuilder() {
        StrBuilder sb = new StrBuilder();
        assertFalse(sb.contains('a'));
    }

    @Test
    public void testContainsChar_singleCharPresent() {
        StrBuilder sb = new StrBuilder("a");
        assertTrue(sb.contains('a'));
    }

    @Test
    public void testContainsChar_singleCharNotPresent() {
        StrBuilder sb = new StrBuilder("b");
        assertFalse(sb.contains('a'));
    }

    @Test
    public void testContainsChar_multipleCharsPresentFirst() {
        StrBuilder sb = new StrBuilder("abc");
        assertTrue(sb.contains('a'));
    }

    @Test
    public void testContainsChar_multipleCharsPresentMiddle() {
        StrBuilder sb = new StrBuilder("abc");
        assertTrue(sb.contains('b'));
    }

    @Test
    public void testContainsChar_multipleCharsPresentLast() {
        StrBuilder sb = new StrBuilder("abc");
        assertTrue(sb.contains('c'));
    }

    @Test
    public void testContainsChar_multipleCharsNotPresent() {
        StrBuilder sb = new StrBuilder("abc");
        assertFalse(sb.contains('d'));
    }

    @Test
    public void testContainsChar_withSpecialCharacter() {
        StrBuilder sb = new StrBuilder("hello!");
        assertTrue(sb.contains('!'));
    }

    @Test
    public void testContainsChar_withWhitespace() {
        StrBuilder sb = new StrBuilder("hello world");
        assertTrue(sb.contains(' '));
    }

    @Test
    public void testContainsChar_withNewline() {
        StrBuilder sb = new StrBuilder("line1\nline2");
        assertTrue(sb.contains('\n'));
    }

    @Test
    public void testContainsChar_withTab() {
        StrBuilder sb = new StrBuilder("col1\tcol2");
        assertTrue(sb.contains('\t'));
    }

    @Test
    public void testContainsChar_afterAppend() {
        StrBuilder sb = new StrBuilder("initial");
        sb.append("test");
        assertTrue(sb.contains('t'));
        assertTrue(sb.contains('e'));
        assertTrue(sb.contains('s'));
        assertFalse(sb.contains('x'));
    }

    @Test
    public void testContainsChar_afterDelete() {
        StrBuilder sb = new StrBuilder("abcdef");
        sb.delete(1, 3); // deletes 'bc'
        assertFalse(sb.contains('b'));
        assertFalse(sb.contains('c'));
        assertTrue(sb.contains('a'));
        assertTrue(sb.contains('d'));
    }

    @Test
    public void testContainsChar_afterReplace() {
        StrBuilder sb = new StrBuilder("apple");
        sb.replace(0, 5, "orange");
        assertTrue(sb.contains('o'));
        assertFalse(sb.contains('p'));
    }

    @Test
    public void testContainsChar_caseSensitivity() {
        StrBuilder sb = new StrBuilder("Hello");
        assertTrue(sb.contains('H'));
        assertFalse(sb.contains('h'));
    }

    @Test
    public void testContainsChar_unicodeCharacter() {
        StrBuilder sb = new StrBuilder("你好世界");
        assertTrue(sb.contains('你'));
        assertFalse(sb.contains('a'));
    }

    @Test
    public void testContainsChar_builderWithNullText() {
        StrBuilder sb = new StrBuilder();
        sb.setNullText("NULL");
        sb.append((Object) null); // Appends "NULL"
        assertTrue(sb.contains('N'));
        assertTrue(sb.contains('U'));
        assertTrue(sb.contains('L'));
        assertFalse(sb.contains('X'));
    }

    @Test
    public void testContainsChar_builderWithZeroLength() {
        StrBuilder sb = new StrBuilder("abc");
        sb.setLength(0);
        assertFalse(sb.contains('a'));
    }

    @Test
    public void testContainsChar_builderWithIncreasedLengthBeyondContent() {
        StrBuilder sb = new StrBuilder("a");
        sb.setLength(5); // buffer is 'a', then 4 null chars
        assertTrue(sb.contains('a'));
        assertFalse(sb.contains('b')); // Should not find 'b'
    }
}
