import org.junit.Test;
import static org.junit.Assert.*;
import org.apache.commons.lang.text.StrBuilder;

public class StrBuilderIndexOfTest {

    @Test
    public void testIndexOfStringInt_BasicFound() {
        StrBuilder sb = new StrBuilder("hello world");
        assertEquals(6, sb.indexOf("world", 0));
        assertEquals(6, sb.indexOf("world", 1));
        assertEquals(6, sb.indexOf("world", 6));
    }

    @Test
    public void testIndexOfStringInt_BasicNotFound() {
        StrBuilder sb = new StrBuilder("hello world");
        assertEquals(-1, sb.indexOf("java", 0));
        assertEquals(-1, sb.indexOf("hello", 6));
    }

    @Test
    public void testIndexOfStringInt_NullString() {
        StrBuilder sb = new StrBuilder("hello world");
        assertEquals(-1, sb.indexOf(null, 0));
        assertEquals(-1, sb.indexOf(null, 5));
    }

    @Test
    public void testIndexOfStringInt_EmptyString() {
        StrBuilder sb = new StrBuilder("hello world");
        assertEquals(0, sb.indexOf("", 0));
        assertEquals(5, sb.indexOf("", 5));
        assertEquals(11, sb.indexOf("", 11));
        assertEquals(-1, sb.indexOf("", 12)); // startIndex > length
        assertEquals(0, sb.indexOf("", -5)); // negative startIndex treated as 0
    }

    @Test
    public void testIndexOfStringInt_StartIndexNegative() {
        StrBuilder sb = new StrBuilder("abcabc");
        assertEquals(0, sb.indexOf("abc", -1));
        assertEquals(0, sb.indexOf("abc", -100));
        assertEquals(3, sb.indexOf("abc", -1)); // Should find the first one
    }

    @Test
    public void testIndexOfStringInt_StartIndexGreaterThanLength() {
        StrBuilder sb = new StrBuilder("test");
        assertEquals(-1, sb.indexOf("t", 4));
        assertEquals(-1, sb.indexOf("t", 5));
        assertEquals(-1, sb.indexOf("test", 5));
    }

    @Test
    public void testIndexOfStringInt_StartIndexEqualToLength() {
        StrBuilder sb = new StrBuilder("test");
        assertEquals(-1, sb.indexOf("t", 4));
        assertEquals(-1, sb.indexOf("e", 4));
        assertEquals(-1, sb.indexOf("st", 4));
    }

    @Test
    public void testIndexOfStringInt_MultipleOccurrences() {
        StrBuilder sb = new StrBuilder("ababab");
        assertEquals(0, sb.indexOf("ab", 0));
        assertEquals(2, sb.indexOf("ab", 1));
        assertEquals(2, sb.indexOf("ab", 2));
        assertEquals(4, sb.indexOf("ab", 3));
        assertEquals(4, sb.indexOf("ab", 4));
        assertEquals(-1, sb.indexOf("ab", 5));
    }

    @Test
    public void testIndexOfStringInt_SearchStringLongerThanContent() {
        StrBuilder sb = new StrBuilder("short");
        assertEquals(-1, sb.indexOf("longer string", 0));
        assertEquals(-1, sb.indexOf("longer string", 2));
    }

    @Test
    public void testIndexOfStringInt_SearchStringSameLengthAsContent() {
        StrBuilder sb = new StrBuilder("match");
        assertEquals(0, sb.indexOf("match", 0));
        assertEquals(-1, sb.indexOf("match", 1));
    }

    @Test
    public void testIndexOfStringInt_EmptyStrBuilder() {
        StrBuilder sb = new StrBuilder();
        assertEquals(-1, sb.indexOf("anything", 0));
        assertEquals(-1, sb.indexOf("anything", 5));
        assertEquals(0, sb.indexOf("", 0));
        assertEquals(-1, sb.indexOf("", 1));
        assertEquals(0, sb.indexOf("", -1));
    }

    @Test
    public void testIndexOfStringInt_ContentWithSpecialCharacters() {
        StrBuilder sb = new StrBuilder("!@#$%^&*()");
        assertEquals(0, sb.indexOf("!", 0));
        assertEquals(2, sb.indexOf("#", 0));
        assertEquals(2, sb.indexOf("#", 2));
        assertEquals(-1, sb.indexOf("abc", 0));
    }

    @Test
    public void testIndexOfStringInt_ContentWithUnicodeCharacters() {
        StrBuilder sb = new StrBuilder("你好世界");
        assertEquals(0, sb.indexOf("你", 0));
        assertEquals(2, sb.indexOf("世界", 0));
        assertEquals(2, sb.indexOf("世界", 1));
        assertEquals(-1, sb.indexOf("hello", 0));
    }

    @Test
    public void testIndexOfStringInt_SearchAtEndOfContent() {
        StrBuilder sb = new StrBuilder("abcde");
        assertEquals(4, sb.indexOf("e", 0));
        assertEquals(4, sb.indexOf("e", 4));
        assertEquals(-1, sb.indexOf("e", 5));
    }

    @Test
    public void testIndexOfStringInt_SearchSubstringAtEnd() {
        StrBuilder sb = new StrBuilder("abcdefg");
        assertEquals(4, sb.indexOf("efg", 0));
        assertEquals(4, sb.indexOf("efg", 4));
        assertEquals(-1, sb.indexOf("efg", 5));
    }

    @Test
    public void testIndexOfStringInt_LongContent() {
        String longStr = "a".repeat(1000) + "b" + "a".repeat(1000);
        StrBuilder sb = new StrBuilder(longStr);
        assertEquals(1000, sb.indexOf("b", 0));
        assertEquals(1000, sb.indexOf("b", 500));
        assertEquals(1000, sb.indexOf("b", 1000));
        assertEquals(-1, sb.indexOf("b", 1001));
    }

    @Test
    public void testIndexOfStringInt_SearchStringNotPresentAfterStartIndex() {
        StrBuilder sb = new StrBuilder("apple banana orange");
        assertEquals(0, sb.indexOf("apple", 0));
        assertEquals(-1, sb.indexOf("apple", 1));
        assertEquals(6, sb.indexOf("banana", 0));
        assertEquals(6, sb.indexOf("banana", 5));
        assertEquals(-1, sb.indexOf("banana", 7));
    }
}
